insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('earthmodel', 'advanced', 'module', 'm01-one-model-two-blocks', 1, 'What is the operational consequence of laying a fault into a property model?', '["Averaging across it is forbidden by default.", "All of the reported volumes double, one full set per fault side.", "The surfaces must be re-gridded at finer cells.", "The tie table becomes invalid."]'::jsonb, 0, 'A fault claims two populations. Statistics, population and volumes go per block; nothing about grids or ties changes, and totals are preserved by the partition.'),
  ('earthmodel', 'advanced', 'module', 'm01-one-model-two-blocks', 2, 'What does the fault multiply: the mathematics or the bookkeeping?', '["The mathematics: the kriging equations become nonlinear wherever a fault intervenes.", "Both equally.", "Neither: fault polygons are cosmetic overlays for the map display.", "The bookkeeping: the same engines run per label."]'::jsonb, 3, 'Labelling, splitting control points, per-block registers: bookkeeping. The plane fit and kriging equations are untouched; they just see different data sets.'),
  ('earthmodel', 'advanced', 'module', 'm01-one-model-two-blocks', 3, 'Which facts does this tier inherit as forward-quoted, not to be presented as discoveries?', '["The trend plane''s three coefficients.", "The kriged probe value of 0.2914 at the point (1500, 2500).", "The census 326/174 and the block volumes summing to the 45 million m3 anchor.", "The variogram''s range and nugget."]'::jsonb, 2, 'The Associate tier''s closing lesson quoted the census and the block-volume closure. The coefficients, variogram and probe values are this tier''s own work.'),
  ('earthmodel', 'advanced', 'module', 'm01-one-model-two-blocks', 4, 'The golden fault polygon''s six vertices all end in 75 or 25 or 30. What is the design intent?', '["It is coincidence.", "Every edge sits at least 25 m off the node lattice.", "The vertices encode the block census in the pattern of their final digits.", "They align with the three source grids'' origins at (900, 1900) and kin."]'::jsonb, 1, 'Vertices at 975, 1575, 2430 and so on keep the even-odd test away from its edge cases; the census is unambiguous by construction, a courtesy real polygons never extend.'),
  ('earthmodel', 'advanced', 'module', 'm01-one-model-two-blocks', 5, 'Which polygon does the validator REJECT, and under which rule?', '["Three collinear vertices: degenerate, zero shoelace area.", "A concave L shape, because concavity is forbidden by the inside test.", "A clockwise-ordered polygon, whose orientation reverses the inside test.", "A polygon with 6 vertices: too many."]'::jsonb, 0, 'The rules are: at least 3 finite vertices, nonzero area, no self-intersection. Orientation and concavity are explicitly fine; the golden L is concave.'),
  ('earthmodel', 'advanced', 'module', 'm01-one-model-two-blocks', 6, 'Why does the even-odd test suit fault-block labelling?', '["It weights every node by its exact distance to the polygon boundary.", "It is exact even for nodes on edges.", "It handles overlapping polygons gracefully by averaging their labels.", "Orientation-blind, concave-safe, and cheap per edge."]'::jsonb, 3, 'PNPOLY''s virtues are robustness and cost. Its one soft spot is exactly on-edge points, which the fixture''s offsets avoid; overlaps resolve by first-wins, not averaging.'),
  ('earthmodel', 'advanced', 'module', 'm01-one-model-two-blocks', 7, 'A node''s label is decided by what test on what geometry?', '["Distance from the node''s centre to the nearest of the polygon''s vertices.", "The sign of the shoelace sum at the node.", "Even-odd crossing of the node''s centre; first containing polygon wins.", "Area overlap between the node''s full 2500 m2 cell and each polygon in turn."]'::jsonb, 2, 'Centres in or out, no partial membership; label = 1 + first containing polygon''s index, 0 outside all. Area-weighted labels would break the volume closure convention.'),
  ('earthmodel', 'advanced', 'module', 'm01-one-model-two-blocks', 8, 'What does ''label = 1 plus the index of the FIRST containing polygon'' imply for overlapping polygons?', '["The later polygon always wins.", "The overlap silently belongs to the earlier polygon.", "The engine throws a validation error whenever any two polygons overlap.", "The overlap is split evenly between the two polygons'' censuses."]'::jsonb, 1, 'First-wins is the documented tiebreak. The QC is comparing each polygon''s standalone containment count with its assigned census; a shortfall reveals the overlap.'),
  ('earthmodel', 'advanced', 'module', 'm01-one-model-two-blocks', 9, 'Which two locations does the module''s hand test run, with what verdicts?', '["W2''s head (1400, 2200) inside; W3''s (1900, 2700) outside.", "W1''s wellhead outside block 1; W4''s wellhead inside it.", "Both W2 locations inside.", "All four wellheads inside."]'::jsonb, 0, 'One ray crossing at x 1575 puts (1400, 2200) in block 1. W3''s location is east and north of the L entirely. W1 is inside; W4 is not.'),
  ('earthmodel', 'advanced', 'module', 'm01-one-model-two-blocks', 10, 'The panel profile is drawn along y = 2200. Why that row?', '["It is the model''s central row.", "It avoids every control point, keeping the profile neutral between wells.", "It is the only row of the frame carrying all 25 of its nodes live.", "It crosses the fault AND carries W2''s control point."]'::jsonb, 3, 'The row shows the per-block discontinuity and the one data point east of the boundary in the same picture; W2''s point sits at y 2200 precisely because its hole runs due east.'),
  ('earthmodel', 'advanced', 'module', 'm01-one-model-two-blocks', 11, 'Which panel control is NOT one of the population explorer''s three?', '["The nugget.", "The range.", "The clamp toggle.", "The method (krige, trend, constant)."]'::jsonb, 2, 'The panel exposes the method and the variogram''s two assumed numbers. The clamp belongs to the Associate framework and is not an assumption of this tier.'),
  ('earthmodel', 'advanced', 'module', 'm01-one-model-two-blocks', 12, 'Block 1''s profile segment never moves under any control setting. Why?', '["The fault polygon clips the effect of the controls at its boundary.", "Its only data is W1, so every method paints the constant 0.315.", "The panel caches block 1''s segment for rendering speed between changes.", "Block 1''s nodes are dead in the framework."]'::jsonb, 1, 'One control point makes constant, trend-fallback and kriging all produce the same flat value. The invariance is a data property, not a rendering artefact.'),
  ('earthmodel', 'advanced', 'module', 'm01-one-model-two-blocks', 13, 'The field-wide weighted porosity is 0.290. What is it the porosity OF, once the fault seals?', '["Nothing: it describes neither block, one being 0.315 and the other 0.286.", "Block 0 exactly.", "Block 1 exactly.", "The arithmetic average rock of the whole field, both blocks included."]'::jsonb, 0, 'Sealed blocks are separate populations. The field mean sits between the block means and equals neither; publishing it unlabelled is the error the tier exists to prevent.'),
  ('earthmodel', 'advanced', 'module', 'm01-one-model-two-blocks', 14, 'What is graded with tolerance ZERO in this capstone?', '["The kriged porosity at W1.", "The trend probe at (1250, 2250).", "Zone A''s bulk volume in block 1.", "The block 1 node count of 174."]'::jsonb, 3, 'Counting is exact or broken. The kriged-at-well field carries 0.0005, the trend probe 0.001, and the block volume 0.01 million m3.'),
  ('earthmodel', 'advanced', 'module', 'm01-one-model-two-blocks', 15, 'Why is the kriged value AT well W1 a good graded field?', '["It changes with every nugget choice, testing the learner''s sweep.", "It is the hardest number to compute.", "It tests the honor-the-data convention, not arithmetic.", "It requires solving the largest linear system anywhere in the course."]'::jsonb, 2, 'The answer is W1''s own 0.315 at ANY valid nugget, because C(0) equals the sill. Implementations using the other nugget convention miss it, which is the point.'),
  ('earthmodel', 'advanced', 'module', 'm02-the-census', 1, 'Hand-count block 1: what are the two rectangles and their node counts?', '["Southern panel 11 by 9 (99) plus arm 5 by 11 (55), keeping off the edges.", "One rectangle of 174 nodes.", "Southern panel 12 by 10 (120) plus arm 6 by 9 (54), totalling 174.", "Southern panel 12 columns by 9 rows plus arm 6 columns by 11 rows."]'::jsonb, 3, 'Columns at x 1000..1550 under y 2430 give 12 x 9; columns 1000..1250 above give 6 x 11. 108 + 66 = 174, and 500 - 174 = 326.'),
  ('earthmodel', 'advanced', 'module', 'm02-the-census', 2, 'Which inequality slip produces 12 columns by EIGHT rows for the southern panel?', '["Counting the polygon''s six vertices as additional inside nodes.", "Confusing dx with dy.", "Assuming the first inside row is row 1 when row 0 already qualifies.", "Using strictly-less instead of less-or-equal at the 2430 boundary edge."]'::jsonb, 2, 'Rows index from 0, and y 2000 is inside 1975 to 2430. Solve the inequality at BOTH ends: r from 0 through 8 is nine rows. The 2430 bound excludes row 9 either way.'),
  ('earthmodel', 'advanced', 'module', 'm02-the-census', 3, 'The polygon''s area is 436,500 m2; the census books 435,000 m2. What is the correct reading?', '["The census dropped 0.6 of a node.", "Two different questions: enclosed area versus captured node cells.", "A labelling bug worth exactly 1,500 m2 that should be fixed before use.", "The shoelace formula is approximate for polygons with concave corners."]'::jsonb, 1, 'Node-centre capture with full-cell booking never equals polygon area exactly; the gap shrinks with cell size. Neither number is wrong; they answer differently.'),
  ('earthmodel', 'advanced', 'module', 'm02-the-census', 4, 'Why do volumes use the census convention rather than exact polygon-clipped areas?', '["Thickness lives at nodes; one consistent rule buys exact closure.", "Clipping is patented.", "Polygon-clipped areas cannot be computed reliably for concave shapes.", "Because the booked difference always favours the operator''s reported volume."]'::jsonb, 0, 'Exact-area accounting needs thickness on cell fragments where none is stored, and a mixed convention would leak volume at every boundary cell, destroying the closure audit.'),
  ('earthmodel', 'advanced', 'module', 'm02-the-census', 5, 'What bounds the census-versus-area discrepancy?', '["The sill of the variogram.", "The number of polygon vertices divided by the frame''s node count.", "Nothing: it is unbounded.", "Boundary length times half the cell size, shrinking linearly with the cell."]'::jsonb, 3, 'It is a boundary effect: 3,200 m of perimeter times 25 m bounds the worst case, and the realised 1,500 m2 is small because the offsets make strips cancel.'),
  ('earthmodel', 'advanced', 'module', 'm02-the-census', 6, 'What certifies that labelling produced a PARTITION?', '["The block volumes coming out positive in both of the blocks.", "The labels array coming back nonempty from the labelling call.", "The census sums to the frame''s node count.", "The polygon validated."]'::jsonb, 2, 'Every node exactly one label is what per-block statistics rest on, and the closing sum is its visible certificate. Validation checks the polygon, not the assignment.'),
  ('earthmodel', 'advanced', 'module', 'm02-the-census', 7, 'Two compartment polygons tile a field but were drawn with a small gap. What happens?', '["The census fails to close, short by exactly the gap''s node count.", "The gap''s nodes land in block 0 and the census still closes.", "The engine throws a gap error.", "The gap''s nodes are assigned automatically to the nearer of the polygons."]'::jsonb, 1, 'Closure survives because outside-all is itself a label. The tell is block 0 being implausibly large; closure plus per-label plausibility together catch what either alone misses.'),
  ('earthmodel', 'advanced', 'module', 'm02-the-census', 8, 'How does the same partition logic apply to control points?', '["They are labelled by the same test.", "Control points are exempt from labelling.", "They are labelled by their well''s spud date.", "Each point gets a fractional membership."]'::jsonb, 0, '3 + 1 = 4 is the closure that catches a dropped point, and the provenance tile''s per-block wells count surfaces it.'),
  ('earthmodel', 'advanced', 'module', 'm02-the-census', 9, 'Labels were computed on a stale 25 x 21 frame; volumes run on 25 x 20. What catches it?', '["Nothing: the extra row''s labels are silently ignored by the volume pass.", "The nugget validation.", "The polygon''s self-intersection test, which sees the extra row.", "The length check: 525 labels against 500 nodes fails at once."]'::jsonb, 3, 'Structural mismatches are exactly what closure-style checks exist for, and the volume engine also throws when grid lengths disagree with the thickness frame.'),
  ('earthmodel', 'advanced', 'module', 'm02-the-census', 10, 'What does the census provide to every downstream per-block statistic?', '["Its variogram.", "Its provenance star in the population summary.", "Its denominator: the defensible node set each mean and volume sums over.", "Its tolerance."]'::jsonb, 2, 'Block porosities and volumes divide by or sum over these node sets. An off-by-one census books a node''s rock to the wrong side of a sealing fault.'),
  ('earthmodel', 'advanced', 'module', 'm02-the-census', 11, 'Why is a fractional ''cell count'' like 174.6 not publishable?', '["It is publishable, provided error bars accompany the fraction.", "Cells are booked whole; 174.6 is the area in a cell costume.", "Rounding rules forbid one decimal.", "The fractional count varies from run to run with the random seed."]'::jsonb, 1, 'Dividing shoelace area by cell area manufactures a fraction no accounting uses. The two legitimate numbers are 174 cells booked and 436,500 m2 enclosed, each labelled as what it is.'),
  ('earthmodel', 'advanced', 'module', 'm02-the-census', 12, 'Moving the southern boundary from x 1575 to 1525 changes the census how?', '["Block 1 loses the nine southern rows'' column 11.", "Block 1 gains nine nodes from block 0''s side.", "Nothing changes until 1524.9.", "Block 1 loses eleven nodes."]'::jsonb, 0, 'Column 11 sits at x 1550, now outside. Nine southern rows carry it, so nine nodes cross to block 0, and closure holds at 165 + 335 = 500.'),
  ('earthmodel', 'advanced', 'module', 'm02-the-census', 13, 'Which claim about block labels is TRUE?', '["They prove the fault seals.", "They imply two independent fluid contacts, one per block, immediately.", "They add the fault''s throw to the surfaces on the downthrown side.", "They quarantine doubt: block 1''s geometry is uncontested by any well."]'::jsonb, 3, 'Labels are accounting. Sealing needs fault-rock or pressure evidence; contacts belong to ReservoirCalc; the golden surfaces are deliberately unfaulted. Localising doubt is what the cut genuinely buys.'),
  ('earthmodel', 'advanced', 'module', 'm02-the-census', 14, 'The polygon is a vertical curtain. What does that approximation cost on a DIPPING fault?', '["Double-counted nodes along the trace.", "A failed validation.", "Block assignment error that grows with depth as the true trace migrates.", "Nothing: dip never affects labels computed in map view, at any depth."]'::jsonb, 2, 'A dipping fault''s trace moves with depth; a single map trace assigns deep nodes by a shallow boundary. The golden fault is vertical by fiat, and the simplification is documented.'),
  ('earthmodel', 'advanced', 'module', 'm02-the-census', 15, 'What is the fastest audit for ''did anyone''s data move blocks since last month''?', '["Compare the two means.", "Diff the per-block control point lists; locations can move.", "Diff the polygon vertex list only, since geometry owns membership.", "Re-run the shoelace area and compare it against the stored value."]'::jsonb, 1, 'Points, not polygons, are the mobile ingredient: a re-survey relocates control points. The polygon diff misses that entirely, as W2''s crossing demonstrates.'),
  ('earthmodel', 'advanced', 'module', 'm03-control-points-cross-the-fault', 1, 'Where does a zone control point stand, by the engine''s convention?', '["At the zone''s point of best porosity along the logged interval.", "At the deepest pick of the zone along the measured hole.", "At the path''s position at the zone''s MD midpoint.", "At the wellhead, always."]'::jsonb, 2, 'MD midpoint landed on the trajectory, weight = interval length. For vertical wells this coincides with the wellhead, which is why the convention is invisible until W2.'),
  ('earthmodel', 'advanced', 'module', 'm03-control-points-cross-the-fault', 2, 'Which control point coordinates carry fifteen significant digits, and why?', '["None: all coordinates are integers.", "W2''s x of 1610.8719179395334: trajectory-derived, not logged.", "W1''s (1100, 2100): the digits reflect high-precision surveying.", "W3''s (1900, 2700): coordinates resampled from the three source grids."]'::jsonb, 1, 'The verticals'' points are wellheads with round coordinates. W2''s location is an arc endpoint plus a hold fraction, and its digits propagate into every downstream weighted statistic.'),
  ('earthmodel', 'advanced', 'module', 'm03-control-points-cross-the-fault', 3, 'Block 1 contains which wellheads and which zone A control points?', '["Wellheads W1 and W2; control point W1 only.", "Wellheads W1 only; control points W1 and W2.", "Wellheads and control points of W1 and W2.", "Wellhead W1; no control points at all."]'::jsonb, 0, 'W2''s rig stands at (1400, 2200), inside; its zone A data stands at x 1610.87, outside. Two rigs, one data point: the tier''s most consequential fact.'),
  ('earthmodel', 'advanced', 'module', 'm03-control-points-cross-the-fault', 4, 'What carried W2''s zone A data across the fault?', '["An error in the even-odd containment test at the boundary.", "The clamp''s 180 fixed BaseB nodes displacing the zone eastward.", "The polygon''s northern arm.", "210.87 m of eastward control point migration in the hold."]'::jsonb, 3, 'The MD midpoint at 1640 lands 210.8719179395334 m east of the head, 35.87 m past the boundary at 1575. Trajectory, convention and containment each did their documented job.'),
  ('earthmodel', 'advanced', 'module', 'm03-control-points-cross-the-fault', 5, 'Why is assigning W2''s zone A value to block 0 physically sensible on this model?', '["Because W2''s porosity matches block 0''s mean.", "It is not sensible, only conventional.", "Its zone A transit runs from x 1568 to 1653.", "Because block 0 has more nodes."]'::jsonb, 2, 'The hole enters the zone 7 m west of the boundary and exits 78 m east: the sampled rock IS mostly block 0. The midpoint got the right answer here; a straddling well is where the convention''s edge lies.'),
  ('earthmodel', 'advanced', 'module', 'm03-control-points-cross-the-fault', 6, 'How fragile is W2''s block assignment?', '["It flips whenever the assumed nugget exceeds the assumed sill.", "About 51 m of MD shift, or 5 degrees of build revision.", "It cannot change at all without physically moving the fault polygon.", "Only a new well could change it."]'::jsonb, 1, 'The margin is 35.87 m of easting, which is 35.87 times sqrt 2 of MD along the hold. Statistics that jump on a survey revision deserve the word fragile in a report.'),
  ('earthmodel', 'advanced', 'module', 'm03-control-points-cross-the-fault', 7, 'Block 1''s zone A porosity is 0.315. What is the support for the VALUE and for its UNIFORMITY?', '["A logged well backs the value; nothing backs the uniformity.", "Both are fully supported by W1.", "Neither is supported; the 0.315 is an interpolated guess.", "The uniformity is supported by the trend fit''s zero residuals."]'::jsonb, 0, 'One well supports one number at one place. Painting it across 174 nodes is the absence of spatial information, not a finding; the regional trend cannot help without crossing the fault.'),
  ('earthmodel', 'advanced', 'module', 'm03-control-points-cross-the-fault', 8, 'Under the trend method, what does block 1''s provenance record?', '["Method trend, wells 1, fell back false.", "Method krige, wells 1, fell back true.", "No record: single-well blocks are skipped.", "Method constant, wells 1, fell back TRUE."]'::jsonb, 3, 'planeFit throws below three points; the ladder catches it and falls to constant, recording the fallback. Kriging, asked for, would RUN with one point, fellBack false.'),
  ('earthmodel', 'advanced', 'module', 'm03-control-points-cross-the-fault', 9, 'What is the graded block 0 weighted porosity, and from which inputs?', '["0.28235504109413956, the unweighted mean of the three block 0 wells.", "0.315, from W1.", "0.28631191845445614, from the block 0 values and MD weights.", "0.2903935560727246, weighting all four of the wells together."]'::jsonb, 2, 'The weighted mean over block 0''s three points. Including W1 reproduces the field-wide constant, which is the exact bookkeeping error the fault forbids.'),
  ('earthmodel', 'advanced', 'module', 'm03-control-points-cross-the-fault', 10, 'Reweighting W2 by its TVD thickness (84.85 for 120) moves the block 0 mean to 0.2848622416729035. What is the finding?', '["The shift is negligible.", "The convention alone is worth more than the tolerance.", "The engine''s stored mean is wrong and should be reseeded.", "Thickness weighting is mandatory whenever any well is deviated."]'::jsonb, 1, 'A 0.00145 move exceeds the tolerance: blocks make small samples, and small samples make conventions consequential. The engine documents MD weighting; the point is knowing what it is worth.'),
  ('earthmodel', 'advanced', 'module', 'm03-control-points-cross-the-fault', 11, 'W2 holds what share of block 0''s total weight?', '["56.9 percent: 120 of 211.", "48.8 percent: 120 of 246.", "33.3 percent: one well of three.", "21.3 percent: 45 of 211."]'::jsonb, 0, 'The fault removed W1''s counterweight, raising W2''s share from its field-wide 48.8. One-well dominance of a block statistic is a standing audit flag.'),
  ('earthmodel', 'advanced', 'module', 'm03-control-points-cross-the-fault', 12, 'Zone B''s block 0 weights are 60, 30, 30. Why is its weighted mean closer to its unweighted one than zone A''s?', '["Zone B has more wells.", "Zone B''s porosities are all equal.", "The engine caps weights at 60.", "Shorter, more even MD transits."]'::jsonb, 3, 'W2''s zone B is only 60 m of hole, a 2 to 1 ratio instead of nearly 3 to 1. Scanning weight shares per block per zone is the two-minute audit that finds such cases.'),
  ('earthmodel', 'advanced', 'module', 'm03-control-points-cross-the-fault', 13, 'A well crosses the fault WITHIN a zone. What does the one-point convention do?', '["Drops the straddling well from both blocks'' control sets.", "Throws a straddling-well error.", "Books the whole value to the MD midpoint''s side.", "Splits the value proportionally to the transit length in each block."]'::jsonb, 2, 'One point per well per zone is the documented collapse; a straddling transit is booked wholly to the midpoint''s side. Knowing the convention''s failure mode is the Expert obligation.'),
  ('earthmodel', 'advanced', 'module', 'm03-control-points-cross-the-fault', 14, 'What single event would upgrade block 1 from lookup to statistics?', '["A longer variogram range reaching across the fault.", "Any second control point in the block.", "A finer model frame with more nodes inside the block.", "A larger sill."]'::jsonb, 1, 'n = 1 is the problem; no parameter fixes it. Two points make a fittable trend along their line and a kriging system with something to weigh.'),
  ('earthmodel', 'advanced', 'module', 'm03-control-points-cross-the-fault', 15, 'Which sentence is the Expert-style report of block 1''s porosity?', '["0.315 carried constant from one well; uniformity unsupported.", "0.315, plus or minus the nugget.", "0.315, confirmed by kriging.", "0.315, the block''s average porosity over its 174 nodes."]'::jsonb, 0, 'Value, method, support and its limits in one line. ''Confirmed by kriging'' is vacuous when kriging must return the constant, and the nugget is not an uncertainty on this number.'),
  ('earthmodel', 'advanced', 'module', 'm04-the-trend-plane', 1, 'What three sums feed the plane fit''s normal equations?', '["The block volumes.", "Coordinate moments and value moments over the points.", "The block census, the variogram sill and the correlation range.", "The residuals of the Professional tier''s twelve-row tie table."]'::jsonb, 1, 'Least squares for v = a + bx + cy builds a 3 x 3 system from coordinate moments and value moments, solved by Gaussian elimination with pivoting.'),
  ('earthmodel', 'advanced', 'module', 'm04-the-trend-plane', 2, 'When does planeFit refuse to run?', '["Under three points, or collinear locations.", "More than ten points.", "Any negative porosity value among the control points.", "Control point weights that do not sum exactly to one."]'::jsonb, 0, 'Three coefficients need three independent equations; collinear locations leave the plane free to rotate. Values and weights are not consulted, the fit being unweighted.'),
  ('earthmodel', 'advanced', 'module', 'm04-the-trend-plane', 3, 'The golden fit recovers phi = 0.38 - 0.00004 x - 0.00001 y with residuals near 1e-16. What does that PROVE?', '["The trend method is highly accurate on real fields of this size.", "Porosity is genuinely linear in position in natural systems.", "The solver uses exact arithmetic.", "The four values lay on a plane before the fit arrived."]'::jsonb, 3, 'Zero misfit with a spare degree of freedom means the data had no off-plane component. The fit returns the recipe the values were cooked from; it says nothing about geology or other data.'),
  ('earthmodel', 'advanced', 'module', 'm04-the-trend-plane', 4, 'Why is near-zero residual at n barely above p WEAK evidence for the trend model?', '["Because p-values need at least 30 samples.", "It is strong evidence; the lesson says so.", "One spare dimension, and derived data fools it entirely.", "Because residuals are always zero for planes."]'::jsonb, 2, 'Small samples flatter simple models. The contrast fixture is ReservoirCalc''s six-well trend with residuals to 8 percent: same method, honest data.'),
  ('earthmodel', 'advanced', 'module', 'm04-the-trend-plane', 5, 'Which property holds for ANY least-squares fit with an intercept, planar data or not?', '["The gradients are negative.", "The residuals sum to zero.", "The residuals are individually zero.", "The intercept equals the data mean."]'::jsonb, 1, 'The intercept''s normal equation forces zero-sum. Individually-zero characterises this fixture''s data; the two zeros carry different messages and must be kept apart.'),
  ('earthmodel', 'advanced', 'module', 'm04-the-trend-plane', 6, 'What is wrong with quoting a = 0.38 as ''the field''s porosity''?', '["It is the plane''s value at (0, 0), a kilometre off the frame.", "Nothing: intercepts are representative values of any fitted field.", "0.38 exceeds the physical maximum porosity any sandstone can carry.", "The intercept has units of metres."]'::jsonb, 0, 'The intercept is bookkeeping at a distant origin. Centred coordinates would make it interpretable; as fitted, no rock in the model carries 0.38.'),
  ('earthmodel', 'advanced', 'module', 'm04-the-trend-plane', 7, 'The graded trend probe is hand-exact: 0.38 - 0.05 - 0.0225 = 0.3075. Which slip gives an answer wrong in the second decimal?', '["Rounding the fitted intercept from 0.38 up to 0.4 before evaluating.", "Evaluating at (1500, 2500).", "Using the interval-weighted mean of the wells as the intercept.", "Applying the gradients per kilometre rather than per metre."]'::jsonb, 3, 'Per-kilometre coefficients with per-metre coordinates inflate the correction terms a thousandfold; units discipline is most of trend hygiene. Evaluating at the kriging probe''s location is a different error with a specific value, 0.295.'),
  ('earthmodel', 'advanced', 'module', 'm04-the-trend-plane', 8, 'What is the plane''s steepest-descent direction and combined gradient magnitude?', '["Due east at 4e-5 of porosity per kilometre of distance.", "Exactly 45 degrees northeast at 5e-5 of porosity per metre.", "About 14 degrees north of east, 4.123e-5 per metre.", "Due north at 1e-5 per metre."]'::jsonb, 2, 'The gradient vector (b, c) points its descent mostly east, tilted north by atan(1/4); magnitude sqrt(16 + 1) x 1e-5. Realised check: 0.0385 over the 950 m from W1 to W4.'),
  ('earthmodel', 'advanced', 'module', 'm04-the-trend-plane', 9, 'Where does the plane predict ZERO porosity at y 2500?', '["x = 934 m.", "x = 8875 m, and negative beyond.", "Nowhere: porosity cannot be negative.", "x = 2200, the frame''s edge."]'::jsonb, 1, '0.38 - 0.025 = 0.00004 x at x 8875. A linear law has no floor; the 934 figure is the distance over which the plane predicts one full observed-range of change, a different diagnostic.'),
  ('earthmodel', 'advanced', 'module', 'm04-the-trend-plane', 10, 'How does kriging behave at (9999, 9999), where the trend goes absurd?', '["It returns the arithmetic mean, 0.2905162808206047.", "It returns a negative porosity as well, just less negative.", "It throws an out-of-range error.", "It returns the weighted constant, 0.2903935560727246."]'::jsonb, 0, 'Beyond the variogram''s reach the weights vanish and the estimate relaxes to the simple kriging mean, which is the ARITHMETIC mean by default. Gentle far fields are their own danger: they look fine.'),
  ('earthmodel', 'advanced', 'module', 'm04-the-trend-plane', 11, 'What is a workable rule for a trend''s trustworthy domain?', '["Anywhere the predicted porosity value comes out positive.", "The whole model frame, always.", "Within one variogram range of the nearest control point.", "The control points'' hull, padded by a well spacing."]'::jsonb, 3, 'Past roughly 900 m here the plane asserts more variation than everything it was shown. The graded probe sits inside the hull''s padding; the same arithmetic at (1250, 2900) would be numerology.'),
  ('earthmodel', 'advanced', 'module', 'm04-the-trend-plane', 12, 'Per-block, the trend on block 0 uses three points. What changed epistemically from the four-point fit?', '["The fit became weighted.", "Nothing at all: three and four points behave alike in a fit.", "Zero residuals became guaranteed for any values.", "The three coefficients changed sharply from the four-point fit."]'::jsonb, 2, 'Three points determine a plane exactly; goodness-of-fit inside small blocks is routinely an illusion of small n. On this planar fixture the coefficients happen to repeat, which is the data''s doing.'),
  ('earthmodel', 'advanced', 'module', 'm04-the-trend-plane', 13, 'What is the trend seam at the fault on the profile row, and what does its SIZE mean?', '["Plus 0.021, block 1 being lower.", "About minus 0.021, an artefact computed in a data gap.", "Exactly zero: trends are continuous.", "Minus 0.0287, the constant method''s seam."]'::jsonb, 1, 'Block 1''s 0.315 against the plane''s 0.294 at the first block 0 node. Each method sizes the cliff differently (constant -0.0287, krige -0.023); none of them measured it.'),
  ('earthmodel', 'advanced', 'module', 'm04-the-trend-plane', 14, 'Why does the seam SHRINK along the northern arm''s boundary?', '["The arm sits further west, where the plane climbs toward W1.", "The arm''s nodes are dead.", "The polygon is thinner there, so fewer nodes carry the jump.", "Kriging smooths the arm."]'::jsonb, 0, 'At (1275, 2600) the plane reads about 0.303 against 0.315: a 0.012 seam versus 0.021 in the south. A single quoted ''discontinuity of 0.02'' is wrong at most latitudes.'),
  ('earthmodel', 'advanced', 'module', 'm04-the-trend-plane', 15, 'A fifth LOGGED point off the plane is added and the fit re-run. What survives?', '["Both properties.", "Neither property.", "The exact fit; zero-sum fails.", "Zero-sum survives; the exact fit does not."]'::jsonb, 3, 'Zero-sum is structural to least squares with an intercept. Exactness was the data''s planarity, which one honest measurement breaks, distributing misfit across all five points.'),
  ('earthmodel', 'advanced', 'module', 'm05-simple-kriging', 1, 'What is the spherical model''s defining behaviour at the range?', '["Correlation is exactly zero from h = 900 m outward.", "Correlation drops to 5 percent there and keeps decaying beyond.", "Correlation jumps discontinuously down to the nugget''s value.", "Correlation becomes negative."]'::jsonb, 0, '1 - 1.5u + 0.5u cubed hits zero at u = 1 and is clamped there. The exponential alternative never touches zero, which is the families'' practical difference.'),
  ('earthmodel', 'advanced', 'module', 'm05-simple-kriging', 2, 'Golden variogram parameters for the model?', '["Spherical, range 300 m, sill 0.025, nugget 0.0025.", "Exponential, range 900 m, sill 0.0025, nugget zero.", "Spherical, range 1800 m, sill 0.00025, nugget 0.0025.", "Spherical, range 900 m, sill 0.0025, nugget 0.00025."]'::jsonb, 3, 'Range 900, sill 0.0025, nugget a tenth of the sill. The engine refuses a nugget at or above the sill, and the fixture also stores an exponential set for comparison.'),
  ('earthmodel', 'advanced', 'module', 'm05-simple-kriging', 3, 'Where does the honor-the-data construction live in the covariance?', '["In the partial pivoting of the Gaussian elimination solver.", "In the weighted mean.", "In C(0) being the full sill, unlike every h above zero.", "In the range parameter, which stretches the covariance to the data."]'::jsonb, 2, 'The jump at h = 0 is what makes the at-well system solve to weight one on that well. A continuous covariance would smooth through the data instead.'),
  ('earthmodel', 'advanced', 'module', 'm05-simple-kriging', 4, 'Why can four control points not estimate a variogram?', '["The porosities are too similar.", "Six pairs cannot fit a curve; assume and sweep instead.", "Variograms need exactly ten pairs.", "The points are collinear."]'::jsonb, 1, 'A real fit bins dozens of wells'' pairwise differences by distance. The Expert posture toward an assumed variogram is sensitivity analysis, which the panel''s controls exist for.'),
  ('earthmodel', 'advanced', 'module', 'm05-simple-kriging', 5, 'Prove the kriged value at W1 is 0.315 for ANY valid nugget, in one step.', '["The target covariances equal that point''s column of A.", "The nugget cancels out inside the engine''s weighted mean.", "W1 is the closest well to itself, so the distance weighting wins outright.", "The mean is set to 0.315."]'::jsonb, 0, 'c0 = A''s k-th column gives w = e_k uniquely; the estimate collapses to the data value. The argument uses C(0) = sill and A''s nonsingularity, nothing about the model family.'),
  ('earthmodel', 'advanced', 'module', 'm05-simple-kriging', 6, 'Ten metres from W1, the golden-nugget estimate is 0.3123130959413633. What is the nugget acting as?', '["A smoothing radius applied around the well.", "Random noise added into the map at every estimated node.", "A depth correction.", "A cliff height at the data."]'::jsonb, 3, 'At nugget 0 the ten-metre value is 0.31465; at 0.002 it is 0.29546, four fifths of the way to the mean. The map is not noisier with more nugget; it is flatter with spikes at wells.'),
  ('earthmodel', 'advanced', 'module', 'm05-simple-kriging', 7, 'Which target''s kriged value is nearly nugget-INSENSITIVE, and why?', '["The value ten metres from W1, inside the cliff.", "All targets are equally sensitive to the nugget''s value.", "The probe at (1500, 2500), far from every cliff.", "The value at W1 itself."]'::jsonb, 2, 'The nugget sweep moves the probe only 0.2916 to 0.2906 across its whole valid span. Sensitivity concentrates near wells; the at-well value is pinned exactly, a different kind of insensitivity.'),
  ('earthmodel', 'advanced', 'module', 'm05-simple-kriging', 8, 'Simple kriging''s default mean, when none is passed, is what?', '["The median of the four control values, robust to their spread.", "The arithmetic mean of the values, 0.2905162808206047.", "The interval-weighted mean of the values, 0.2903935560727246.", "Zero."]'::jsonb, 1, 'The residuals are measured from, and the far field relaxes to, the plain average. The weighted 0.29039 belongs to the constant method; the 0.00012 gap is a designed tripwire.'),
  ('earthmodel', 'advanced', 'module', 'm05-simple-kriging', 9, 'At range 300, the probe returns 0.2905162808206047 exactly. Why?', '["Every well lies beyond 300 m, so the estimate IS the mean.", "The dense solver failed and quietly defaulted to the mean.", "Range 300 makes the covariance system numerically singular.", "The probe coincides with a well."]'::jsonb, 0, 'The nearest point is 319.83 m away; beyond a spherical range, weights are zero. The range dial is physical: the distance beyond which the map stops being about the wells.'),
  ('earthmodel', 'advanced', 'module', 'm05-simple-kriging', 10, 'Range sweep at the probe: 300, 600, 900, 1800 give what shape?', '["Monotone rise toward W2''s value.", "Monotone fall toward zero.", "Constant at the mean.", "0.29052, 0.29047, 0.29143, 0.29247."]'::jsonb, 3, 'At 600, the negative-residual wells W3 and W4 reach the probe while W1''s positive residual barely does; widening to 900 and 1800 lets W1 pull the estimate back up. Weight geometry, not folklore.'),
  ('earthmodel', 'advanced', 'module', 'm05-simple-kriging', 11, 'Exponential versus spherical at the probe, same parameters?', '["Exponential returns the mean exactly.", "Exponential is invalid with a nonzero nugget.", "0.291000548626652 against 0.29142777199229974.", "Identical values by construction."]'::jsonb, 2, 'The families differ by about 0.0004 here, half a grading tolerance. Model-family sensitivity is one more line of the robustness summary a reviewer wants.'),
  ('earthmodel', 'advanced', 'module', 'm05-simple-kriging', 12, 'Kriging block 1 (one well, default mean) yields what map?', '["The field-wide plane.", "The constant 0.315: the lone residual is zero.", "A bullseye decaying smoothly from W1''s value toward zero.", "An error, because kriging needs at least three control points."]'::jsonb, 1, 'mu = 0.315 leaves nothing for the weight to multiply. With an EXPLICIT different mean, the map would decay from the well toward it; the default hides the variogram entirely at n = 1.'),
  ('earthmodel', 'advanced', 'module', 'm05-simple-kriging', 13, 'Why does the ladder let kriging run at n = 1 but not trend?', '["Kriging degrades gracefully; a two-point plane is arbitrary.", "Kriging is newer code.", "Trend is slower.", "It is a bug."]'::jsonb, 0, 'The asymmetry is principled: defined-and-sensible runs, underdetermined throws and falls back VISIBLY, provenance recording which story the map carries.'),
  ('earthmodel', 'advanced', 'module', 'm05-simple-kriging', 14, 'The graded probe is 0.2914277719922997. Which near-miss value convicts which error?', '["0.3075 convicts using the wrong nugget convention at wells.", "0.315 convicts range 300.", "0.29039 convicts using the exponential variogram model instead.", "0.2862746100855956 convicts the per-block three-well map."]'::jsonb, 3, 'The block 0 population at the same location kriges three wells around their own mean: 0.0052 lower. 0.3075 is the trend probe, 0.315 the at-well answer, and 0.29039 the weighted constant: each wrong answer is a right answer to a different question.'),
  ('earthmodel', 'advanced', 'module', 'm05-simple-kriging', 15, 'Summarise the probe''s robustness for review.', '["Robust to everything.", "Sensitive only to the sill, which scales every covariance.", "Nugget-robust, mildly range-sensitive, family-stable.", "Sensitive to every one of the assumed parameters at once."]'::jsonb, 2, 'That sentence, with the sweeps behind it, is what understanding the probe means; producing the digits alone is half-learned.'),
  ('earthmodel', 'advanced', 'module', 'm06-per-block-volume-and-the-workflow', 1, 'State the per-block zone A bulk volumes and their closure.', '["22,500,000 and 22,500,000 m3, the frame split evenly in two.", "31,001,250 and 13,998,750 exactly, closing to within 2 m3.", "435,000 and 436,500 m3.", "31,001,250 and 13,998,749.999999998, closing to zero."]'::jsonb, 3, 'Each node adds into its block register and the total register in one pass, so the audit subtraction returns 0 exactly, in bulk and in cells (326 + 174 = 500).'),
  ('earthmodel', 'advanced', 'module', 'm06-per-block-volume-and-the-workflow', 2, 'What can a NONZERO closure mean on this architecture?', '["A pinched zone crossing the fault boundary.", "A wrong nugget.", "Structural trouble only, never healthy float noise.", "Normal float rounding, safely ignored below about 1 m3."]'::jsonb, 2, 'The blocks'' sum and the total are the same additions grouped differently. Closure is an audit instrument precisely because benign noise cannot produce a violation here.'),
  ('earthmodel', 'advanced', 'module', 'm06-per-block-volume-and-the-workflow', 3, 'Why does the graded block 1 figure end in .999999998?', '["The grading tolerance requires nine decimals of headroom.", "174 float additions land shy of the round hand value.", "The polygon''s area is irrational, and the tail carries it.", "A bug worth reporting."]'::jsonb, 1, 'The engine''s node-sum route and the mean-thickness hand route are both right and differ in the ninth significant figure. Identify which route produced each number before judging either.'),
  ('earthmodel', 'advanced', 'module', 'm06-per-block-volume-and-the-workflow', 4, 'The volume SPLIT moved but the TOTAL did not. What changed?', '["The labels: only labels can move the split.", "The zone thickness grid changed under the resample.", "The clamp counts, redistributed between the blocks.", "The variogram."]'::jsonb, 0, 'No rock moves when a polygon is edited; registers just reassign. Boundary uncertainty is uncertainty in the split, never in the field total.'),
  ('earthmodel', 'advanced', 'module', 'm06-per-block-volume-and-the-workflow', 5, 'Zone B splits 3.11 to 9.69 million m3, block 1 holding 76 percent on 35 percent of the nodes. Why?', '["Block 1''s cells are larger than block 0''s on this frame.", "Zone B''s porosity runs higher in block 1 than anywhere else.", "A closure failure.", "The pinch-out, where zone B is zero, lies in block 0''s east."]'::jsonb, 3, 'The split EXPOSES spatial structure the field total averaged away, which is the constructive reason per-block numbers exist. Porosity plays no role in bulk volume.'),
  ('earthmodel', 'advanced', 'module', 'm06-per-block-volume-and-the-workflow', 6, 'Run block 1''s chain: net, pore, HCPV from bulk 13,998,750 with NTG 0.798, phi 0.315, Sw 0.252.', '["10,469,065, then 3,297,755, then 2,466,721 m3.", "The chain needs a formation volume factor first.", "11,171,002.5, then 3,518,865.7875, then 2,632,111.60905 m3.", "11,171,002.5, then 2,632,111.609, then 3,518,865.79 m3."]'::jsonb, 2, 'Bulk times NTG, times phi, times one minus Sw, in that order, each exact by hand because the block''s properties are constants. The FVF belongs to ReservoirCalc, downstream.'),
  ('earthmodel', 'advanced', 'module', 'm06-per-block-volume-and-the-workflow', 7, 'Why does the hand audit work so cleanly for block 1 and less so for block 0?', '["Block 0''s chain uses different formulas from block 1''s.", "Block 1''s map is one round well; block 0''s are long means.", "Block 0''s closure fails.", "Block 1 has fewer nodes than wells."]'::jsonb, 1, 'A one-well block is the easiest to audit: regroup the round constants and multiply. For sprawling constants, audit the weight SHARES instead.'),
  ('earthmodel', 'advanced', 'module', 'm06-per-block-volume-and-the-workflow', 8, 'What does the HCPV computed here NOT include, and why does the label matter?', '["A contact: it is a property-model number, honestly labelled.", "It excludes block 1.", "It omits the porosity factor from the multiplication chain.", "It is net of royalties."]'::jsonb, 0, 'Volume above a contact is a booking number, owned by ReservoirCalc with its contacts and fluids. Quoting this HCPV as if contact-cut is the classic hand-off error.'),
  ('earthmodel', 'advanced', 'module', 'm06-per-block-volume-and-the-workflow', 9, 'Which edit has the widest downstream reach relative to its size?', '["A polygon vertex nudge of 50 m along the southern boundary.", "A porosity value edit at the block''s dominant well.", "A tolerance change.", "A survey revision: it alone moves data across the fault."]'::jsonb, 3, 'Surveys relocate control points, which can switch blocks and rewrite both blocks'' populations and the volume split. Polygon and value edits stay within predictable registers.'),
  ('earthmodel', 'advanced', 'module', 'm06-per-block-volume-and-the-workflow', 10, 'Name the three refusals that define this tier''s edges.', '["No means, no medians, no modes.", "No closure checks, no provenance records, no visible fallbacks.", "No cross-label averaging, no unsupported methods, no barrels.", "No polygons in the volumes, no wells in the labels, no faults."]'::jsonb, 2, 'Each refusal marks a plausible shortcut made deliberate and visible: cross-fault statistics, silent fallbacks, and booking beyond the mandate.'),
  ('earthmodel', 'advanced', 'module', 'm06-per-block-volume-and-the-workflow', 11, 'A revised BaseB surface arrives. Which Expert-tier quantities change?', '["The variogram, refitted to the revised surface''s relief.", "Zone B''s volumes through thickness; all else stands.", "The census.", "The control point locations of the wells that pick BaseB."]'::jsonb, 1, 'Labels are fault geometry; control points are trajectory products; zone A never touched BaseB. The change flows through thickness into zone B volumes, with closures re-verified.'),
  ('earthmodel', 'advanced', 'module', 'm06-per-block-volume-and-the-workflow', 12, 'The capstone answer 15.66 million m3 for block 1''s bulk convicts what?', '["Using the field mean 36 m instead of the block''s 32.181.", "Using the polygon''s 436,500 m2 area instead of the cells.", "A closure failure.", "Reading block 0''s figure from the tile beside the graded one."]'::jsonb, 0, 'The mean-without-its-denominator error, one ladder-long lesson late. Block 0''s figure is 31.00125; the polygon-area route gives 435,000 x thickness confusion of a different shape.'),
  ('earthmodel', 'advanced', 'module', 'm06-per-block-volume-and-the-workflow', 13, 'Blocks 0 and 1 have zone A mean thicknesses 38.038 and 32.181 m. What is the field mean and how?', '["35.1 m: the plain average of the two block mean thicknesses.", "38.0 m: the larger block''s value.", "32.2 m: the smaller block''s value, since it controls the split.", "36.0 m: the node-count-weighted blend of the two."]'::jsonb, 3, 'Block means blend by node counts, and the blend recovers the Associate tier''s 36 exactly. The plain average of block means is meaningless without their denominators.'),
  ('earthmodel', 'advanced', 'module', 'm06-per-block-volume-and-the-workflow', 14, 'Which field of the capstone tests reading comprehension of UNITS?', '["The kriged at-well value, which must carry four decimals.", "The trend probe, which must be quoted in percent.", "Block 1''s bulk, entered as 13.99875 in millions.", "The census."]'::jsonb, 2, 'The instruction says enter in units of 10^6 m3; a raw 13998750 fails on units, not geology. The other fields are dimensionless or counts.'),
  ('earthmodel', 'advanced', 'module', 'm06-per-block-volume-and-the-workflow', 15, 'What closes the Earth Modeling ladder''s story arc?', '["The capstone waiving its tolerances on the final field.", "The hand-off to ReservoirCalc, which owns contacts and recovery.", "The model being uploaded onward into the seismic interpretation module.", "The clamp is finally turned off."]'::jsonb, 1, 'The container is built, tied, cut, filled and audited. Barrels are the next discipline''s business, and the fixtures were designed to face each other across that boundary.'),
  ('earthmodel', 'advanced', 'final', null, 1, 'A sealing fault enters a one-tank property model. What single change follows everywhere?', '["The variogram range halves.", "Every statistic acquires a block label; no cross-boundary averaging.", "All porosities must be re-logged against the new fault-block boundaries.", "The model frame doubles its resolution so cells stop straddling the trace."]'::jsonb, 1, 'The fault claims two populations; labelling, per-block population and per-block volumes are that claim carried through the bookkeeping.'),
  ('earthmodel', 'advanced', 'final', null, 2, 'Why can the block 1 census be defended to tolerance ZERO?', '["Two rectangles of nodes, 108 plus 66, all edges clear of the lattice.", "Because the labelling engine is deterministic across repeated runs of the model.", "Because 174 is divisible by 6, matching the northern arm''s column count.", "It cannot; zero tolerance is aspirational."]'::jsonb, 0, 'Axis-aligned edges, off-lattice offsets, and a two-rectangle L make the count hand-checkable. Determinism alone would defend any wrong count equally.'),
  ('earthmodel', 'advanced', 'final', null, 3, 'Which pair of numbers answers ''how big is block 1'' and how do they differ?', '["174 nodes against 326: the census pair, counts on both sides of the fault.", "45 and 13.99875 million m3, the anchor and the block''s share of it.", "The two block porosities.", "436,500 m2 enclosed by the polygon; 435,000 m2 booked by 174 cells."]'::jsonb, 3, 'Enclosed area is polygon-only; booked area is polygon AND frame. Volumes use the booked set for closure''s sake, and a report should label which is quoted.'),
  ('earthmodel', 'advanced', 'final', null, 4, 'The even-odd test is run on node centres. What does that convention buy at volume time?', '["Sub-cell accuracy wherever the fault boundary slices through boundary cells.", "Nothing at volume time: the volume pass ignores the labels entirely.", "One rule end to end: a node speaks for its whole cell, so volumes close.", "Faster labelling."]'::jsonb, 2, 'One consistent rule end to end is what makes the closure an audit instrument. Mixing area-weighted labels with node-summed volumes would leak at every boundary cell.'),
  ('earthmodel', 'advanced', 'final', null, 5, 'Rank the polygon validator''s three refusals by what they protect against.', '["They are stylistic lint inherited from the polygon library, safely ignorable in a model of this size.", "Bad vertices poison containment; zero area labels nothing; bowties have no inside.", "All three protect against slow rendering of the map display.", "They protect the census tolerance only."]'::jsonb, 1, 'Each rule maps to a specific silent failure. Orientation and concavity, by contrast, are legitimately free.'),
  ('earthmodel', 'advanced', 'final', null, 6, 'W2''s wellhead is in block 1 and its zone A control point in block 0. Which three correct mechanisms compose this?', '["A fault-crossing trajectory, the midpoint convention, exact containment.", "A survey typo, a polygon digitising bug, and accumulated floating point rounding.", "The clamp, the surface resampler, and the model frame''s chosen origin.", "None: the situation is contradictory."]'::jsonb, 0, 'Each ingredient did its documented job; composition produced a well counting for a block it was not drilled in. Data location is derived, and that is the tier''s deepest lesson.'),
  ('earthmodel', 'advanced', 'final', null, 7, 'Block 1''s porosity is exactly W1''s 0.315. What turned a four-well field into a one-well statistic?', '["W1''s superior log quality relative to the three eastern wells of the set.", "The nugget discounting the three eastern wells out of the block.", "The trend fit rejecting three points.", "The fault passing between W2''s rig and its migrated data point."]'::jsonb, 3, 'The 210.87 m migration left W1 alone west of the line. Nothing statistical happened; geometry did it, which is why no parameter can undo it.'),
  ('earthmodel', 'advanced', 'final', null, 8, 'Which number is graded: the block 0 weighted porosity. Which is its most seductive WRONG neighbour?', '["0.315, W1''s own logged porosity value carried across the line.", "0.0025, the sill.", "0.2903935560727246: the four-well mean, the fault forgotten.", "0.3075, the plane-trend probe read at the wrong location."]'::jsonb, 2, 'The graded 0.28631191845445614 uses three wells and weights 120, 45, 46. The field-wide constant is the pre-fault answer, a correct computation of an obsolete question.'),
  ('earthmodel', 'advanced', 'final', null, 9, 'What does the fitted plane''s machine-zero residual on four points reveal?', '["Porosity is planar within measurement error.", "The values were generated from that plane.", "The trend method is exact in general.", "The solver used rational arithmetic."]'::jsonb, 1, 'One spare degree of freedom carrying zero misfit says the data had no off-plane component. Derived values return their generator; suspicion of perfect fits is the Expert reflex.'),
  ('earthmodel', 'advanced', 'final', null, 10, 'Why is the trend probe graded value 0.3075 reachable in three hand multiplications?', '["The recovered coefficients are round by construction.", "The engine rounds every probe it serves to four decimal places.", "Because the probe location sits exactly on one of the control points.", "It is not; a solver is required."]'::jsonb, 0, '0.38 - 0.05 - 0.0225. The fixture''s generosity has a purpose: any wrong digit convicts a units slip or a wrong-question answer, not arithmetic.'),
  ('earthmodel', 'advanced', 'final', null, 11, 'The trend crosses zero porosity at x 8875 (y 2500). What is the correct use of that fact?', '["As grounds to relocate the model frame west of the zero contour.", "To cap the range at 8875.", "As grounds to reject the trend method everywhere on the frame.", "A domain lesson: a linear law has no floor; bound it by data."]'::jsonb, 3, 'The absurdity is manufactured by distance, not malfunction. Hull-plus-spacing bounds where the plane has standing; the method stays useful inside them.'),
  ('earthmodel', 'advanced', 'final', null, 12, 'Contrast the two methods'' far fields in one sentence.', '["Both far fields return zero porosity beyond the data hull.", "Kriging diverges with distance while the trend saturates at the sill.", "The trend runs smoothly to nonsense; kriging retreats to the mean.", "Both diverge."]'::jsonb, 2, 'A gradient is forever; collapsed weights are the mean. The kriged far field LOOKS fine, which is the more dangerous honesty failure when data footprints go unchecked.'),
  ('earthmodel', 'advanced', 'final', null, 13, 'Why does C(0) = sill (not sill minus nugget) matter to the capstone?', '["It only matters for the exponential model, whose tail never reaches zero.", "It makes the at-well value the well''s own, which 0.0005 polices.", "It doubles the sill.", "It sets the far field to zero rather than to the mean."]'::jsonb, 1, 'The discontinuity at zero separation is the honor-the-data choice; the other convention smooths through wells and misses the field at any nugget.'),
  ('earthmodel', 'advanced', 'final', null, 14, 'The nugget rises from 0.00025 to 0.002. Describe the map''s change near and far from wells.', '["Cliffs at wells steepen; far probes barely move.", "The whole map shifts down by 0.0008, the nugget''s increase halved.", "The wells lose their exactness in proportion to the nugget.", "The far field diverges."]'::jsonb, 0, 'The nugget is cliff height, not blur: honoured wells, faster jumps off them, flatter plains. Sensitivity concentrates near data.'),
  ('earthmodel', 'advanced', 'final', null, 15, 'Kriging at range 300 returns the mean at the probe. What is the physical reading of the range dial?', '["The maximum well spacing the population method will tolerate before failing.", "The effective cell size of the interpolated output map.", "The polygon''s buffer width.", "The distance beyond which the map stops being about the wells."]'::jsonb, 3, 'All wells sit beyond 300 m of the probe, so weights vanish. Sweeping the dial and watching where estimates collapse calibrates it faster than theory.'),
  ('earthmodel', 'advanced', 'final', null, 16, 'Why does the probe''s range sweep DIP below the mean at 600 before rising above it at 900?', '["The nugget dominates the covariance system at the shorter ranges.", "The sweep is monotone in the range; there is no such dip.", "The nearer negative-residual wells reach it before W1 does.", "Numerical instability at 600."]'::jsonb, 2, 'W3 and W4 (residuals -0.0135, -0.0140) sit at 447 and 652 m; W1 (+0.0245) at 566. The order in which the range admits them shapes the curve: weight geometry.'),
  ('earthmodel', 'advanced', 'final', null, 17, 'One engine, two means. Which consumer reads which?', '["Kriging reads the median of the control values, robust against outliers.", "Kriging anchors on the arithmetic mean; constant serves the weighted.", "Both read the weighted mean.", "Both consumers read the arithmetic mean of the control values."]'::jsonb, 1, 'The 0.00012 gap is a designed tripwire: a far-field pin catches any refactor that swaps the kriging default; the fixture stores constant_weighted by name.'),
  ('earthmodel', 'advanced', 'final', null, 18, 'What map does kriging paint in a one-well block, and why?', '["The constant 0.315: the lone residual is zero, so nothing varies.", "A radial decay from the well''s value down to zero beyond the range.", "The regional trend, imported from the all-well fit.", "An error map."]'::jsonb, 0, 'mu equals the lone value, so every target returns it. An EXPLICIT mean would revive the variogram; the default hides it at n = 1, gracefully.'),
  ('earthmodel', 'advanced', 'final', null, 19, 'Same map, two provenance stories: ''krige, wells 1, no fallback'' versus ''constant, wells 1, fell back''. Which request produced each?', '["Requesting constant produced both of the records on different runs.", "The first is a bug.", "The two stories are interchangeable labels for one computation.", "Requesting krige gave the first; requesting trend gave the second."]'::jsonb, 3, 'Kriging runs at n = 1; trend throws and the ladder lands on constant, recording the fallback. The metadata, not the map, carries the difference, and review reads metadata.'),
  ('earthmodel', 'advanced', 'final', null, 20, 'Why record provenance per block per property on EVERY population run?', '["To seed the random number generator that draws the simple kriging weights.", "Provenance is optional streaming metadata.", "A fallback constant looks exactly like a fitted model; only the record tells.", "For billing purposes."]'::jsonb, 2, 'Maps cannot testify about their own pedigree. The panel''s fallback star is the record surfaced; a silent-fallback engine lets one-well constants masquerade.'),
  ('earthmodel', 'advanced', 'final', null, 21, 'Blocks'' bulk volumes sum to the total with error literally zero. What architectural fact delivers that?', '["The frame carries an even node count, so the halves pair off.", "Each node adds into block and total registers in one pass.", "The volumes are computed in integer cubic metres throughout.", "The polygon area is rational."]'::jsonb, 1, 'Same additions, different grouping. That is why nonzero closure always means structural trouble, never acceptable float noise, on this computation.'),
  ('earthmodel', 'advanced', 'final', null, 22, 'Which two numbers on this model demonstrate ''a mean is meaningless without its denominator'' at the Expert tier?', '["Block thickness means 38.038 and 32.181 blending to the field''s 36.0.", "The sill and the nugget, whose ratio sets the smoothness of the kriged map.", "The census pair of 326 and 174, denominators themselves.", "The two probes."]'::jsonb, 0, 'The Associate lesson returns two tiers up: the field mean is the area-weighted blend of block means, and neither block carries 36 m.'),
  ('earthmodel', 'advanced', 'final', null, 23, 'What does zone B''s 76-percent-in-block-1 split expose that the field total hid?', '["That block 1 carries systematically better porosity throughout the zone.", "A labelling error.", "Nothing: per-block splits are arbitrary bookkeeping artefacts.", "That the clamp''s pinch-out of zone B lives in the east, in block 0."]'::jsonb, 3, 'Per-block accounting surfaces spatial structure. The tie table''s eastern BaseB contradiction and this split are the same geology seen from two tiers.'),
  ('earthmodel', 'advanced', 'final', null, 24, 'The hand chain for block 1 runs 13,998,750 x 0.798 x 0.315 x 0.748. Which factor does a CONTACT eventually replace or refine?', '["The 2500 m2 cell area.", "The bulk volume itself.", "The (1 - Sw) fraction.", "The NTG."]'::jsonb, 2, 'This tier''s HCPV is a property-model number, honestly labelled ''no contact applied''. Contacts, fluids and recovery are the ReservoirCalc ladder''s business.'),
  ('earthmodel', 'advanced', 'final', null, 25, 'Which single revision can rewrite BOTH blocks'' porosity statistics without touching porosity data?', '["A frame origin shift of 1 m, which relabels every boundary node.", "A survey re-run moving a control point across the fault.", "A new colour ramp on the panel''s porosity profile.", "A sill change."]'::jsonb, 1, 'Membership, not values, is what the survey moves: 120 units of weight and a value change sides, and both weighted means jump discontinuously.'),
  ('earthmodel', 'advanced', 'final', null, 26, 'What margin protects W2''s block assignment, and in what currency?', '["35.87 m of easting, about 51 m of MD along the hold.", "174 nodes.", "0.001 of porosity, the tolerance on the block''s graded mean.", "One 50 m grid cell exactly, by the fixture''s design."]'::jsonb, 0, 'The point stands at x 1610.87 against the boundary''s 1575. Cliffs in derived statistics deserve explicit margins, and this one is a survey revision away.'),
  ('earthmodel', 'advanced', 'final', null, 27, 'A candidate answers the census as 326. What happened?', '["They mislabelled the nine boundary-column nodes of the south.", "They used the polygon''s shoelace area divided by the cell size.", "They counted vertices.", "They reported block 0: right count, wrong block."]'::jsonb, 3, 'Reading comprehension failures grade identically to ignorance at tolerance zero. The area route would give 174.6, and nine-node errors give 165 or 183.'),
  ('earthmodel', 'advanced', 'final', null, 28, 'Why does the capstone pair an at-well kriging field with a far-probe kriging field?', '["So the grader can average the two answers into one score.", "Because the pair shares one tolerance across both fields.", "One tests the honoring convention, one the full solve.", "Redundancy for partial credit."]'::jsonb, 2, '0.315 at 0.0005 catches convention errors; 0.29143 at 0.001 catches solver, mean and parameter errors. Tolerances differ because the failure modes do.'),
  ('earthmodel', 'advanced', 'final', null, 29, 'The block 0 trend fit uses exactly three points. What did the block lose relative to the four-point fit?', '["Its per-block provenance record.", "Its capacity for self-criticism.", "Its three fitted plane coefficients.", "Its weights."]'::jsonb, 1, 'Exactly-determined fits cannot register misfit. On this planar fixture the coefficients repeat; on real data the loss is the diagnosis, not the numbers.'),
  ('earthmodel', 'advanced', 'final', null, 30, 'What honest sentence covers the fault seam''s size in a report?', '["The seam exists because the blocks share no data; its size is method bookkeeping.", "The fault physically throws 0.021 of porosity across its plane, measured by the model.", "The seam''s existence in the maps proves that the fault seals.", "The seam is measurement noise."]'::jsonb, 0, 'No well constrains the west side within 450 m of the seam. Existence is the model''s honest claim; size is bookkeeping, and it varies along the fault.'),
  ('earthmodel', 'advanced', 'final', null, 31, 'Which check would catch a containment test silently dropping one control point?', '["The shoelace area check on the polygon''s six vertices.", "The sill validation inside the kriging parameter checks.", "The seam size.", "Per-block wells counts failing to sum to the well set."]'::jsonb, 3, 'Partition closure applies to points as to nodes. The provenance tile surfaces the per-block counts precisely so the failure cannot hide.'),
  ('earthmodel', 'advanced', 'final', null, 32, 'Why is the golden model''s fault treated as a vertical curtain, and what would real fault sticks change?', '["To halve the labelling computation across the model''s twenty node rows.", "Because the polygon validator requires vertical curtains only.", "v1 models the trace; dipping sticks make labels depth-dependent.", "Because all real faults are vertical."]'::jsonb, 2, 'The curtain is a documented simplification, exact for vertical faults. The Seismolord ladder''s fault objects carry dip; adopting them turns labelling into a 3D question.'),
  ('earthmodel', 'advanced', 'final', null, 33, 'What does the ladder hand ReservoirCalc, precisely?', '["The contact depths per block, ready for volumetric booking.", "Per-block bulk and property maps with provenance.", "STOIIP per block, already risked and ready to book.", "Recovery factors."]'::jsonb, 1, 'The division of labour is binding both ways: this course stops at pore-volume-without-contact; the booking course starts from exactly these deliverables.'),
  ('earthmodel', 'advanced', 'final', null, 34, 'A reviewer asks whether block 1 could hold a different fluid contact from block 0. What is this model''s answer?', '["No position taken: contacts and sealing are outside the mandate.", "Yes: the census difference between the blocks proves independence.", "No: the surfaces are continuous.", "Yes: the porosity jump across the seam implies separate contacts."]'::jsonb, 0, 'Blocks are accounting; the two-contacts question is real and belongs to the discipline that owns contacts, with fault-rock or pressure evidence.'),
  ('earthmodel', 'advanced', 'final', null, 35, 'Rank these edits by volume-split impact: polygon vertex +50 m; survey rebuild of W2; porosity value edit.', '["The porosity edit first, since porosity scales every one of the registers.", "All three equal.", "None of the three edits affects the split in any register.", "Polygon and survey move the split; porosity never touches bulk."]'::jsonb, 3, 'Bulk volume sees labels and thickness only. The polygon moves nodes; the survey can move a well''s data and weight; porosity edits change pore, not bulk.'),
  ('earthmodel', 'advanced', 'final', null, 36, 'What makes the number 174 durable evidence in a way 0.29142777 is not?', '["It is stored in the committed golden fixture, safe from any regeneration.", "It is graded twice, once per tier of the ladder.", "It is discrete and hand-derivable; the probe rests on assumptions.", "It is larger."]'::jsonb, 2, 'Counts survive parameter sweeps untouched; estimates carry their assumptions. Reports should lean on the discrete skeleton and label the estimates.'),
  ('earthmodel', 'advanced', 'final', null, 37, 'Which lesson from the Professional tier did this tier convert from curiosity to consequence?', '["The kelly bushing convention shared by the four golden wells.", "The 211 m migration, which became block membership.", "The ratio factor.", "The bilinear blend weights at W2''s TopA landing point."]'::jsonb, 1, 'The migration was a tile in the tie explorer; the fault line turned it into the shape of block 1''s entire statistics.'),
  ('earthmodel', 'advanced', 'final', null, 38, 'The whole-model 45 million m3 anchor plays what role at this tier?', '["The closure target the block volumes must sum back to.", "An obsolete number superseded by the per-block accounting.", "The graded field.", "A rounding convenience for the hand-audit chains."]'::jsonb, 0, 'The Associate anchor does work two tiers up, exactly as promised: a split that misses it has lost or doubled nodes. The graded field is block 1''s share.'),
  ('earthmodel', 'advanced', 'final', null, 39, 'Which practices would have caught a hypothetical bug where labels were computed with (y, x) swapped?', '["The nugget sweep, which is directly sensitive to the coordinate order.", "The trend residuals, which swap sign under the exchange.", "The hand chain.", "The census: a non-174 count the hand rectangles catch at once."]'::jsonb, 3, 'Geometry bugs surface in counting first. The L is not symmetric under coordinate swap, so the rectangles'' arithmetic convicts the swap on sight.'),
  ('earthmodel', 'advanced', 'final', null, 40, 'What is the tier''s final epistemic habit, stated once?', '["Prefer kriging to trends whenever both methods can run.", "Trust the panel''s tiles over the engine wherever they disagree.", "Derive the number, then state what it does not claim.", "Round to three figures."]'::jsonb, 2, 'The census that is not an area, the exact fit that is not evidence, the honoured well not trusted an inch away, the closure that certifies partitions only: models earn trust by knowing their edges.'),
  ('earthmodel', 'advanced', 'final', null, 41, 'Zone A control points: W1 (1100, 2100), W2 (1610.87, 2200), W3 (1900, 2700), W4 (2050, 2150). Which wells anchor the northern arm of block 1?', '["W3 only, projecting in from across the model''s northern half.", "None: the arm holds no control point at all.", "W1 and W3, one anchoring each end of the arm.", "W1 only."]'::jsonb, 1, 'W1 sits in the southern panel; every other point is east. The arm''s 66 nodes carry the constant 0.315 with zero nearby support, the uniformity caveat in its sharpest form.'),
  ('earthmodel', 'advanced', 'final', null, 42, 'The exam''s last word: why does this fixture trade realism for checkability?', '["So every number is derivable and every convention pinned.", "Because real field data is confidential and cannot be shipped.", "To reduce file size.", "It does not; the fixture is as realistic as the field data allows."]'::jsonb, 0, 'Planar porosity and off-lattice polygons are admitted constructions. The bargain, stated openly, is the same across the course family: exactness where learning needs it.');
